window.SUBJECTS = window.SUBJECTS || [];
window.SUBJECTS.push({"id":"phy","n":"Physics","tab":"Physics","w":"Motion, heat and sound, light, electricity and magnetism.","topics":[{"id":"mechanics","n":"Motion, Force, Units and Measurement","qs":[{"id":"q1579","q":"Which instrument can be used to measure internal and the external dimensions of an object?","o":["Viscometer","Vernier Caliper","Wattmeter","Venturimeter"],"a":1,"x":"A Vernier caliper measures internal and external dimensions (and depth) accurately, to about 0.1 mm.","e":"A screw gauge (micrometer) is more precise, to about 0.01 mm.","src":["Patwari 18 Sep 2022 S1"]},{"id":"q0491","q":"A type of motion in which all parts of an object move in the same direction in a given time is called _________ motion.","o":["translation","rotational","periodic","oscillation"],"a":0,"x":"In translatory motion every part of a body moves the same distance in the same direction in the same time.","e":"A car on a straight road. A spinning fan is rotational motion.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0531","q":"Which among the following is an example of double class 1 lever?","o":["Scissors","Wheelbarrow","Broom","Nut cracker"],"a":0,"x":"Scissors are a double class-1 lever: two levers joined at a pivot (fulcrum) that sits between the effort (handles) and the load (blades).","e":"Wheelbarrow and nutcracker: class 2. Broom and tongs: class 3.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0572","q":"The attractional force applied by the earth on an object in the downward direction is called _____________.","o":["Muscular Force","Air Resistance","Frictional Force","Gravitational Force"],"a":3,"x":"The force with which Earth pulls an object downward is gravitational force; for an object, this pull is its weight (W = mg).","e":"g is about 9.8 m/s² at Earth's surface.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0730","q":"The concepts of work and energy share which one of the following units of measurement?","o":["Watt","Ohm","Joule","Ampere"],"a":2,"x":"Work and energy share the SI unit joule (J): 1 J = 1 newton × 1 metre.","e":"Power is measured in watts: 1 W = 1 J per second.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q6779","q":"Which among the following is an example of a second class lever?","o":["Scissors","Wheelbarrow","Broom","Hockey Stick"],"a":1,"x":"In a second-class lever, such as a wheelbarrow or nutcracker, the load is between the fulcrum and the effort.","e":"Scissors: first class; broom: third class.","src":["Junior Assistant 25 Aug 2021"]},{"id":"q1790","q":"Which of the following is not an equation of an object moving at uniform acceleration?","o":["v = u + at","u = 1/(at2)","2as = v2 – u2","s = ut + 1/(2at2)"],"a":1,"x":"The three equations of uniformly accelerated motion are v = u + at, s = ut + ½at² and v² − u² = 2as. 'u = 1/(at²)' is not one of them.","e":"v = u + at is the first.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q2867","q":"If mass of body on earth is 10, then weight is ______ kg.","o":["45","90","49","98"],"a":3,"x":"Weight = mass × g = 10 × 9.8 = 98 newtons.","e":"W = mg.","src":["Junior Clerk 17 Nov 2021 S1"],"k":"Weight is measured in newtons, not kg as the options say; the number 98 is right."},{"id":"q6108","q":"Which of the following is true regarding mass and weight of an object? I. If mass = 10, then weight = 98 II. If weight = 5, then mass = 49 III. Weight of an object is maximum at poles. IV. Weight of an object is minimum at equators.","o":["I, III and IV","II, III and IV","III and IV","Only II"],"a":0,"x":"Weight = mass × g, so 10 kg weighs 98 N. g is greatest at the poles and least at the equator, so weight is too.","e":"","src":["Junior Clerk 9 Nov 2021 S1"]},{"id":"q6202","q":"Which of the following statement regarding energy is correct? I. Kinetic energy = (mv2)/2 II. Gravitational potential energy = mgh III. Power = energy used to do work","o":["I and II","II and III","I and III","I, II and III"],"a":0,"x":"Kinetic energy = ½mv² and gravitational potential energy = mgh; power is the rate of doing work, not the energy used.","e":"","src":["Junior Clerk 9 Nov 2021 S3"]},{"id":"q1337","q":"What is the SI unit of energy?","o":["Newton","Joule","Mole","Ampere"],"a":1,"x":"The SI unit of energy is the joule (J), the same as for work.","e":"1 kilowatt-hour (the electricity 'unit') = 3.6 × 10⁶ J.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q4044","q":"The energy that an object possesses because of its motion, is known as ___________ energy.","o":["electrical","chemical","kinetic","potential"],"a":2,"x":"Kinetic energy is the energy a body has because of its motion (½mv²); potential energy comes from its position.","e":"","src":["Stenographer 23 Apr 2021 S1"]},{"id":"q4894","q":"The SI unit of weight is ______.","o":["Sigma","Newton","Ohm","Mole"],"a":1,"x":"Weight is a force, so its SI unit is the newton.","e":"","src":["Stenographer 26 Nov 2021 S1"]},{"id":"q5406","q":"What is “c” in E = mc2 equation in Einstein's theory of special relativity?","o":["Weight of the Substance","Speed of Light","Molecular Weight","Atomic Weight"],"a":1,"x":"In E = mc², c is the speed of light in vacuum (about 3 × 10⁸ m/s).","e":"","src":["Personal Assistant 29 Nov 2021 S1"]},{"id":"q4484","q":"Certain insects can stand on the surface of the water because of the following property of the water?","o":["Surface Tension of Water","Osmotic Pressure of Water","Viscosity of Water","Surface Relaxation of Water"],"a":0,"x":"Surface tension lets insects such as water striders stand on water.","e":"","src":["Office Superintendent 24 Oct 2021 S2"]},{"id":"q3423","q":"Which of the following is correct? I. Sum of kinetic and heat energy is called mechanical energy. II. Potential energy + kinetic energy = Constant at all points for an object.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":1,"x":"Mechanical energy is kinetic plus potential energy, not kinetic plus heat energy. For a freely falling object, potential plus kinetic energy stays constant (conservation of energy). So only II is correct.","e":"","src":["Store Keeper 19 Apr 2021 S2"]},{"id":"q3459","q":"Which of the following is correct about force? I. A force can act on an object only being in its contact. II. Liquids do not exert any pressure on walls of their containers.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":3,"x":"Both are wrong: forces like gravity and magnetism act without contact, and liquids do exert pressure on the walls of their container.","e":"","src":["Store Keeper 19 Apr 2021 S3"]},{"id":"q3631","q":"Which of the following scientists had discovered that time period of a given pendulum is constant?","o":["Galileo Galilie","Nicolas Copernicus","Johannes Kepler","Albert Einstein"],"a":0,"x":"Galileo discovered that a given pendulum takes the same time for each swing (its time period is constant), watching a swinging lamp in a church.","e":"","src":["Fire Operator 20 Apr 2021 S2"]},{"id":"q3634","q":"What is the Spring Balance used to measure?","o":["Force","Temperature","Length","Voltage"],"a":0,"x":"A spring balance measures force (such as weight) by how much a spring stretches.","e":"","src":["Fire Operator 20 Apr 2021 S2"]},{"id":"q3669","q":"Which of the following scientists had discovered the value of the universal gravitation constant?","o":["Joseph Priestly","Henry Cavendish","Issac Newton","Joseph Black"],"a":1,"x":"Henry Cavendish first measured the gravitational constant G (1798) with a torsion balance.","e":"G = 6.67 × 10⁻¹¹ N m² kg⁻².","src":["Fire Operator 20 Apr 2021 S3"]},{"id":"q3672","q":"If an athlete is running, then in which of the following tracks shape will his velocity changes continuously even though the magnitude remains the same?","o":["Square shaped track","Hexagonal shaped track","Octagonal shaped track","Circular track"],"a":3,"x":"On a circular track the direction of motion changes all the time, so velocity changes even at constant speed.","e":"","src":["Fire Operator 20 Apr 2021 S3"]},{"id":"q3811","q":"Which of the following statement is correct? I. Sliding friction is smaller than static friction. II. Rolling friction is smaller than sliding friction.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Static friction > sliding friction > rolling friction, so both statements are correct.","e":"That is why wheels and ball bearings reduce friction.","src":["Fire Operator 22 Apr 2021 S1"]},{"id":"q2699","q":"In the question given below, there are two statements marked as Assertion (A) and Reason (R). Mark your answer as per the codes in options : Assertion (A): Heavier objects falls slowly than lighter objects. Reason (R) : The force of gravity is more for heavier objects.","o":["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"a":3,"x":"Without air resistance all objects fall at the same rate (g = 9.8 m/s²), so the assertion is false. The force of gravity is indeed greater on a heavier object, so the reason is true, but acceleration is the same.","e":"Galileo: a feather and a stone fall together in a vacuum.","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q2709","q":"The time rate of change of displacement of a body is called __________.","o":["acceleration","velocity","force","friction"],"a":1,"x":"The time rate of change of displacement is velocity; the rate of change of velocity is acceleration.","e":"Velocity = displacement ÷ time.","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q2744","q":"In the question given below, there are two statements marked as Assertion (A) and Reason (R). Mark your answer as per the codes in options : Assertion (A): We slip while dancing on a shiny floor. Reason (R) : Friction is less on a shiny surface.","o":["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"a":0,"x":"We slip on a shiny floor because a smooth surface gives less friction; the assertion and reason are both true, and the reason explains the assertion.","e":"Friction depends on surface roughness.","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q2754","q":"Which among the following instruments is used in aircrafts for measuring altitudes?","o":["Altimeter","Ammeter","Anemometer","Barometer"],"a":0,"x":"An altimeter measures altitude in aircraft. An ammeter measures current, an anemometer wind speed and a barometer air pressure.","e":"","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q2824","q":"__________ is a force which opposes the relative motion of the two bodies when one body actually moves or tries to move over the surface of another body.","o":["Acceleration","Velocity","Force","Friction"],"a":3,"x":"Friction is the force that opposes the relative motion of two surfaces in contact.","e":"Friction always acts against motion.","src":["Ahlmad 16 Oct 2021 S3"]},{"id":"q4008","q":"What is the acceleration responsible for circular motion called?","o":["Rotational force","Central force","Centripetal force","Centrifugal force"],"a":2,"x":"The centre-seeking (centripetal) force and acceleration keep a body moving in a circle.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S3"]},{"id":"q4337","q":"Centrifugal force can be defined as:","o":["The force with which the weight of a body may be considered to act.","The product of force multiplied by the perpendicular distance from the line of action to the pivot point.","The force arising from the body's inertia while it is moving in a circular path and is directed away from the centre.","The force arising from the body's inertia while it is moving in a circular path and is directed towards the centre."],"a":2,"x":"Centrifugal force is the apparent outward force, due to the body's inertia, felt on a body moving in a circle.","e":"Centripetal = towards the centre; centrifugal = away.","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S3"]},{"id":"q4079","q":"__________ law is a law of physics that states that the force needed to extend or compress a spring by some distance scales linearly with respect to that distance.","o":["Charles's","Hooke's","Ohm's","Kepler's"],"a":1,"x":"Hooke's law: within the elastic limit, the force to stretch or compress a spring is proportional to the extension (F = kx).","e":"","src":["Jr. Telephone Operator 23 Apr 2021 S2"]},{"id":"q1012","q":"In scientific research, which system of units is primarily used?","o":["US standard system","CGS system","Customary system","SI system"],"a":3,"x":"The SI (International System of Units, 1960) is used worldwide in science: metre, kilogram, second, ampere, kelvin, mole and candela.","e":"SI has 7 base units.","src":["PRT 19 Feb 2026 S2"]},{"id":"q4182","q":"One of the uses of centripetal/centrifugal force is to:","o":["Remove water from clothes in a washing machine","To track earth's water and ice","Create molecules out of atoms","Slow down/stop cars"],"a":0,"x":"A washing machine's spin cycle uses centrifugal action to throw water out of clothes.","e":"","src":["Nursery Teacher 23 Oct 2021 S1"]},{"id":"q4183","q":"Application of increasing torque is seen in which of these:","o":["reducing the length of a lever","placing door knob as far away from the hinge as possible","placing a heavier pulley instead of a light one","catching a ball"],"a":1,"x":"Putting a door knob far from the hinge increases torque for the same force (torque = force × distance).","e":"","src":["Nursery Teacher 23 Oct 2021 S1"]},{"id":"q1425","q":"Who among the following gave the three laws of planetary motion?","o":["Newton","Rutherford","Kepler","Faraday"],"a":2,"x":"Johannes Kepler gave the three laws of planetary motion (1609–1619): elliptical orbits, equal areas in equal times, and T² ∝ r³.","e":"Newton later explained them with his law of gravitation.","src":["TGT 25 Jun 2023 S2"]},{"id":"q1709","q":"Which of the following device is used to measure Altitude?","o":["Altimeter","Microscope","Thermometer","Hygrometer"],"a":0,"x":"An altimeter measures altitude.","e":"Hygrometer – humidity.","src":["TGT 10 Sep 2021 S2"]},{"id":"q1730","q":"Which among the following is not a vector quantity?","o":["Force","Acceleration","Speed","Momentum"],"a":2,"x":"Speed is a scalar; force, acceleration and momentum are vectors.","e":"","src":["TGT 10 Sep 2021 S3"]},{"id":"q1896","q":"Mohan jumped from bed to floor. When he hit the floor, he felt a force applied by the floor. Which law of physics, Mohan experienced?","o":["Newton 1st Law","Newton 2nd Law","Newton 3rd Law","Hubble's Law"],"a":2,"x":"The floor pushing back on Mohan is Newton's third law: every action has an equal and opposite reaction.","e":"","src":["TGT 11 Sep 2021 S3"]},{"id":"q2370","q":"Which of the following statement is correct? I. Weight of a body is the force with which the earth attracts it. II. Value of force of gravity is greater at equator than at the poles.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Weight is the force with which the Earth attracts a body; gravity is stronger at the poles than at the equator, so II is wrong.","e":"","src":["TGT 14 Sep 2021 S3"]},{"id":"q5815","q":"The car seat-belts in our everyday lives works on which of the following concepts?","o":["Gravity","Inertia","Kinetic energy","Pressure"],"a":1,"x":"Seat belts work on inertia: they stop the body from moving forward when the car stops suddenly.","e":"","src":["TGT 5 Sep 2021 S2"]},{"id":"q5832","q":"In the question given below, there are two statements marked as Assertion (A) and Reason (R). Mark your answer as per the codes in options. Assertion (A): A ship rises as it enters the sea from a river. Reason (R): The density of sea water is lower as compared to river water.","o":["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"a":2,"x":"A ship rises as it enters the sea because sea water is denser than river water, so the reason as given is false.","e":"","src":["TGT 5 Sep 2021 S3"]},{"id":"q8846","q":"The dimension [T] represents which physical quantity?","o":["Tension","Time","Torque","Temperature"],"a":1,"x":"In dimensional analysis, [T] stands for time.","e":"","src":["Special Educator 14 Mar 2026"]},{"id":"q6513","q":"Which among the following is not an example of contact forces?","o":["Frictional","Spring","Muscular","Magnetic"],"a":3,"x":"Magnetic force acts without contact; friction, spring force and muscular force are contact forces.","e":"","src":["PGT 30 Jul 2021 S1"]},{"id":"q7059","q":"Which of the following is an equation of uniform acceleration?","o":["v = u + at","v + u = at","va = ut","v = ut + a"],"a":0,"x":"v = u + at is the first equation of uniformly accelerated motion.","e":"","src":["PGT 11 Jul 2021"]},{"id":"q7251","q":"Which among the following statements is incorrect?","o":["A motion which repeats itself identically after a fixed interval of time, is called a periodic motion.","A periodic motion taking place to and fro or back and forth about a fixed point, is called rotational motion.","The revolution of earth around the sun is periodic motion.","The motion of a cyclist running on a straight road is Rectilinear motion."],"a":1,"x":"To-and-fro motion about a fixed point is oscillatory (vibratory) motion, not rotational motion, so statement B is wrong.","e":"","src":["PGT 29 Jul 2021 S1"]},{"id":"q8415","q":"A car placed on the top of a hill, a compressed spring, and a bent bow are all examples of which energy?","o":["Kinetic energy","Chemical energy","Mechanical energy","Potential energy"],"a":3,"x":"A car on a hilltop, a compressed spring and a bent bow all store potential energy.","e":"","src":["PGT 21 Jun 2023 S2"]},{"id":"q8471","q":"The distance between the centre of a compression and an adjacent rarefaction is equal to _________.","o":["half the wavelength","twice the wavelength","the wavelength","one-third of the wavelength"],"a":0,"x":"The distance from a compression to the next rarefaction is half a wavelength.","e":"","src":["PGT 22 Jun 2023 S2"]},{"id":"q8506","q":"If the kinetic energy of an object is increased by 44%, the momentum of the object will be increased by:","o":["10%","20%","44%","22%"],"a":1,"x":"Momentum varies as the square root of kinetic energy: √1.44 = 1.2, so momentum rises 20%.","e":"","src":["PGT 22 Jun 2023 S2"]},{"id":"q1915","q":"The sharp and loud sound produced due to the air pressure variation associated with shock waves produced by a supersonic aircraft are called as:","o":["Echo","Sonic Boom","Infrasound","Doppler Effect"],"a":1,"x":"A supersonic aircraft's shock waves produce a loud sound called a sonic boom.","e":"","src":["Scientific Assistant (Ballistics) 11 Sep 2021 S3"]},{"id":"q2797","q":"Find the energy possessed by an object of mass 20 kg when it is at a height of 800 cm above the ground? Take ‘g’ = 10 m s-2","o":["160000 J","160 J","1600 J","16 J"],"a":2,"x":"Potential energy = mgh = 20 × 10 × 8 = 1,600 J.","e":"","src":["Inspecting Officer 16 Oct 2021 S1"]},{"id":"q3080","q":"Which among these is a scalar quantity?","o":["Pressure","Displacement","Force","Momentum"],"a":0,"x":"Pressure is a scalar; displacement, force and momentum are vectors.","e":"","src":["Draftsman 17 Oct 2021 S1"]},{"id":"q3113","q":"Which of the following statements is incorrect? If an object sinks in water means-","o":["The density of the object is more that of the density of water","The upthrust of water on the object is less than the weight of the object","The upthrust of water on the object is more than the weight of the object","The density of the water is less that of the density of object"],"a":2,"x":"An object sinks when upthrust is less than its weight, so saying upthrust is more is wrong.","e":"","src":["Legal Assistant 17 Oct 2021 S2"]},{"id":"q3177","q":"Which of the following units is equal to 6 feet?","o":["1 fathom","1 decibel","1 kilometre","1 centimetre"],"a":0,"x":"One fathom equals 6 feet; it is used to measure water depth.","e":"","src":["Technical Assistant (Plastic) 18 Nov 2021 S2"]},{"id":"q3333","q":"The area enclosed by velocity-time graph and the time axis is equal to the magnitude of __________.","o":["Distance","Displacement","Acceleration","Momentum"],"a":1,"x":"The area under a velocity–time graph gives displacement.","e":"","src":["Senior Scientific Assistant (Biology) 18 Sep 2021 S2"]},{"id":"q4140","q":"Every object will remain at rest or in uniform motion in a straight line unless compelled to change its state by the action of an external force is the Newton's:","o":["First Law","Second Law","Third Law","Fourth Law"],"a":0,"x":"Newton's first law (inertia): a body stays at rest or in uniform motion unless an external force acts.","e":"","src":["Manager (Public Relations) 23 Oct 2021 S2"]},{"id":"q4904","q":"Angstrom is a unit of length which is equal to:","o":["0.001 centimetre","0.1 millimetre","0.1 nanometre","0.001 metre"],"a":2,"x":"One ångström is 10⁻¹⁰ m, or 0.1 nanometre.","e":"","src":["Assistant Bacteriologist 26 Nov 2021 S2"]},{"id":"q5229","q":"A constant force acts on an object of mass 10 kg for a duration of 4 second. It increases the object’s velocity from 3 metre/second to 7 metre/second. What is the magnitude of applied force?","o":["5 N","15 N","10 N","20 N"],"a":2,"x":"F = m(v − u)/t = 10 × (7 − 3)/4 = 10 N.","e":"","src":["Senior Scientific Assistant (Chemistry) 27 Sep 2021 S2"]},{"id":"q5630","q":"Which of the following principle/law describes energy conservation for ideal fluids in steady, or streamline, flow and is the basis for many engineering applications.","o":["Archimedes Principle","Avagadro’s Law","Bernoulli's Principle","Stefan’s Law"],"a":2,"x":"Bernoulli's principle describes energy conservation in the steady flow of ideal fluids.","e":"","src":["Labour Welfare Inspector 30 Nov 2021 S2"]},{"id":"q5670","q":"Which one of the following phenomena is defined as the time rate at which work is done or energy is transferred?","o":["Force","Power","Collision","Motion"],"a":1,"x":"Power is the rate of doing work or transferring energy; its unit is the watt.","e":"","src":["Driver 30 Nov 2021 S3"]},{"id":"q7354","q":"Which of the following statement is correct? I. Mass remains same on earth and moon. II. mass = weight × g","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Mass stays the same on the Earth and the Moon; weight = mass × g, so mass = weight ÷ g, not weight × g.","e":"","src":["Physical Education Teacher 2 Aug 2021"]}]},{"id":"heat","n":"Heat, Sound and Thermodynamics","qs":[{"id":"q1750","q":"Which of the following statement regarding sound is correct? I. Frequency is inversely proportional to time period. II. Speed of sound in water > speed of sound in oxygen. III. The repeated reflection that results in persistence of sound is called echo.","o":["I and II","II and III","I and III","I, II and III"],"a":0,"x":"Frequency = 1 / time period, and sound travels faster in water (about 1,480 m/s) than in oxygen (about 316 m/s). Persistence of sound from repeated reflections is reverberation, not echo, so only I and II are right.","e":"Echo = one clear reflection; reverberation = many overlapping ones.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1793","q":"Which of the following statement regarding sound is NOT correct? I. The audible range of hearing for average human beings is 30Hz-30kHz. II. Outer ear is called pinna. III. Ultrasounds can be used to detect cracks and flows in metal blocks. IV. Frequencies higher than 15kHz are called ultrasound.","o":["I, II and IV","II and III","I and IV","Only III"],"a":2,"x":"Human hearing is about 20 Hz–20 kHz (not 30–30 kHz), and ultrasound is above 20 kHz (not 15 kHz), so I and IV are wrong. The pinna is the outer ear, and ultrasound does detect flaws in metal.","e":"Infrasound < 20 Hz < audible < 20 kHz < ultrasound.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1946","q":"Which of the following pair is/are correct? I. Large amplitude = Loud sound II. Higher frequency = Higher pitch","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Larger amplitude gives a louder sound, and higher frequency gives a higher pitch, so both pairs are correct.","e":"Amplitude → loudness; frequency → pitch.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q2528","q":"What kind of waves are sound waves?","o":["Longitudinal waves","Transverse waves","Surface waves","Electromagnetic waves"],"a":0,"x":"Sound waves are longitudinal: air particles vibrate back and forth along the direction the wave travels, forming compressions and rarefactions.","e":"Light waves are transverse.","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q2907","q":"Through which of the following can the sound travel? I. Gas II. Vaccum III. Solid","o":["I and II","I and III","II and III","I, II and III"],"a":1,"x":"Sound needs a medium, so it travels through gases, liquids and solids but not through a vacuum.","e":"Fastest in solids.","src":["Junior Clerk 17 Nov 2021 S2"]},{"id":"q10122","q":"Which of the following is helpful for exploring and mapping the ocean? I. SONAR II. RADAR","o":["Only II","Neither I nor II","Only I","Both I and II"],"a":2,"x":"SONAR, which uses sound waves, is used to explore and map the ocean; RADAR uses radio waves.","e":"","src":["Assistant Superintendent 20 Jul 2024 S3"]},{"id":"q3593","q":"Consider an experiment given below. Take a tin can with a lid. Fill it approximately half with water. Heat it till the water boils. Remove from heat. Now, pour fresh water over the can. What happens to the shape of the can?","o":["Can will expand","Can gets distorted","Can will burst","No change in the structure of the can"],"a":1,"x":"When cold water is poured on the hot can, the steam inside condenses, lowering the pressure inside; the outside air pressure then crushes the can.","e":"It shows that air exerts pressure.","src":["Fire Operator 20 Apr 2021 S1"]},{"id":"q2711","q":"As per the _________ law of Thermodynamics, heat given to a substance is equal to sum of change in internal energy and work done.","o":["Zeroth","First","Second","Third"],"a":1,"x":"The First Law of Thermodynamics: heat supplied = change in internal energy + work done (Q = ΔU + W), a form of conservation of energy.","e":"","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q2977","q":"In which of the following cases are sonic booms produced?","o":["When sound waves travel from lighter to denser medium.","When an object travels at a speed more than the speed of sound.","When an object enters the ionosphere.","When an object travels at the speed of light."],"a":1,"x":"A sonic boom occurs when an object travels faster than sound (supersonic), producing shock waves.","e":"Faster than Mach 1.","src":["Fee Collector Sub Inspector Auction Recorder 17 Nov 2021 S3"]},{"id":"q4288","q":"Which of the following substances do not show anomalous expansion?","o":["Phosphorus","Mercury","Water","Silica"],"a":1,"x":"Mercury expands normally when heated; water (between 0 °C and 4 °C) and some substances such as silica expand anomalously.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S2"]},{"id":"q0898","q":"Which law of thermodynamics states that heat cannot spontaneously flow from a colder object to a hotter object without external intervention?","o":["First","Second","Third","Zeroth"],"a":1,"x":"The second law of thermodynamics (Clausius form) says heat cannot flow on its own from a colder body to a hotter one; a refrigerator needs work to do it.","e":"First law: energy is conserved. Second law: entropy rises.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0948","q":"Which of the following is an example of an open system?","o":["A thermos flask with a tight lid","Hot coffee kept in a cup","A closed bottle of soda","A sealed pressure cooker"],"a":1,"x":"An open system exchanges both matter and energy with its surroundings: hot coffee in an open cup loses heat and water vapour. A closed system (sealed bottle, pressure cooker) exchanges only energy; an isolated one (thermos) exchanges neither.","e":"Open = matter + energy; closed = energy only; isolated = nothing.","src":["PRT 18 Feb 2026 S2"]},{"id":"q1004","q":"What is the key component inside a decibel meter that helps detect sound pressure?","o":["Magnetic coil","Microphone","LED sensor","Optical fiber"],"a":1,"x":"A decibel (sound level) meter uses a microphone to pick up sound pressure changes and turn them into an electrical signal.","e":"The decibel scale is logarithmic: +10 dB means 10 times the sound intensity.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1452","q":"What is the SI unit of thermodynamic temperature as per the International System of Units?","o":["Kelvin","Thermos","Fahrenheit","Celsius"],"a":0,"x":"The kelvin (K) is the SI unit of thermodynamic temperature; 0 K is absolute zero (−273.15°C).","e":"K = °C + 273.15.","src":["TGT 25 Jun 2023 S3"]},{"id":"q2327","q":"At 25 degreeC in which of the following substance speed of sound is maximum?","o":["Sea water","Distilled water","Ethanol","Methanol"],"a":0,"x":"Among these liquids at 25 °C, sound travels fastest in sea water (about 1,531 m/s).","e":"","src":["TGT 14 Sep 2021 S1"]},{"id":"q3312","q":"Humans can detect sounds that fall within which of these frequency ranges?","o":["50Hz-50kHz","10Hz-10kHz","20Hz-20kHz","30Hz-30kHz"],"a":2,"x":"Humans can hear sounds of about 20 Hz to 20 kHz.","e":"Below 20 Hz: infrasonic; above 20 kHz: ultrasonic.","src":["TGT 18 Sep 2021 S1"]},{"id":"q5816","q":"Sound waves travelling through air are _______________ waves.","o":["longitudinal","transverse","gravitational","surface"],"a":0,"x":"Sound waves in air are longitudinal waves.","e":"","src":["TGT 5 Sep 2021 S2"]},{"id":"q5992","q":"______ of a sound wave determines loudness of sound.","o":["Speed","Frequency","Wavelength","Amplitude"],"a":3,"x":"The loudness of a sound depends on its amplitude; pitch depends on frequency.","e":"","src":["TGT 8 Sep 2021 S1"]},{"id":"q6045","q":"On which of the following temperature, the density of water is highest?","o":["37°F","38°F","39°F","40°F"],"a":2,"x":"Water is densest at 4 °C, which is about 39 °F.","e":"","src":["TGT 8 Sep 2021 S2"]},{"id":"q6303","q":"Which of the following is correct for the speed of sound?","o":["Speed = wavelength / frequency","Speed = frequency / wavelength","Speed = wavelength × frequency","Speed × frequency = wavelength"],"a":2,"x":"Speed of a wave = wavelength × frequency (v = fλ).","e":"","src":["TGT 9 Oct 2021 S2"]},{"id":"q7576","q":"Which of the following is correct about sound? I. Large amplitude – Loud sound II. High frequency – Low pitch","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"A large amplitude gives a loud sound; a high frequency gives a high pitch, not a low one.","e":"","src":["TGT 8 Aug 2021"]},{"id":"q3044","q":"Which of the following is NOT an example of convectional current?","o":["Boiling of Water","Ocean currents","Campfires","Ironing of clothes"],"a":3,"x":"Ironing clothes transfers heat by conduction; boiling water, ocean currents and campfires involve convection.","e":"","src":["Special Educator 17 Oct 2021 S1"]},{"id":"q0822","q":"Which of the following law states that ‘two systems in thermal equilibrium with a third system separately are in thermal equilibrium with each other'?","o":["The first law of thermodynamics","Fourier's law","Joule's First law","The zeroth law of thermodynamics"],"a":3,"x":"The zeroth law of thermodynamics: if two systems are each in thermal equilibrium with a third, they are in equilibrium with each other. This is what makes a thermometer work.","e":"First law: energy conservation (ΔU = Q − W).","src":["PGT 26 Sep 2025"]},{"id":"q6475","q":"___________ law states that black body radiation has different peaks of temperature at wavelengths that are inversely proportional to temperatures.","o":["Wien's","Fourier's","Ampere's","Coulomb's"],"a":0,"x":"Wien's displacement law: the peak wavelength of black-body radiation is inversely proportional to temperature.","e":"","src":["PGT 30 Jul 2021 S2"]},{"id":"q7058","q":"No medium is required for transfer of heat by ______.","o":["conduction","convection","radiation","both convection and radiation"],"a":2,"x":"Radiation needs no medium to transfer heat; conduction and convection do.","e":"","src":["PGT 11 Jul 2021"]},{"id":"q2229","q":"The maximum density of water occurs at _____.","o":["4°C","0°C","-5°C","100°C"],"a":0,"x":"Water is densest at 4°C.","e":"","src":["Laboratory Assistant (Lie Detection) 13 Sep 2021 S1"]},{"id":"q2577","q":"Water remains cool in an earthern pitcher due to the process of ______.","o":["Condensation","Evaporation","Precipitation","Assimilation"],"a":1,"x":"Water stays cool in an earthen pot because evaporation through its pores removes heat.","e":"","src":["Technical Assistant (Medical Electronics) 16 Nov 2021 S2"]},{"id":"q3966","q":"The Sun's energy is produced by the nuclear fusion of ______.","o":["Hydrogen","Helium","Nitrogen","Krypton"],"a":0,"x":"The Sun's energy comes from nuclear fusion of hydrogen into helium.","e":"","src":["Trained Graduate Teacher (Deaf & Dumb) Tier-I 22 Nov 2021 S2"]},{"id":"q4720","q":"The poorest conductor of heat:","o":["Lead","Iron","Calcium","Graphite"],"a":0,"x":"Of these, lead is the poorest conductor of heat.","e":"","src":["Laboratory Assistant (HRD Quality Control) 25 Sep 2021 S1"]},{"id":"q7400","q":"Which of the following statement(s) is/are correct? I. Speed of sound in solids > Speed of sound in liquids II. Speed of sound in liquids > Speed of sound in gases","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Sound travels fastest in solids, slower in liquids and slowest in gases.","e":"","src":["Physical Education Teacher 2 Aug 2021"]}]},{"id":"light","n":"Light and Optics","qs":[{"id":"q1620","q":"Which of the following is NOT an example of refraction of light?","o":["Moonlight","bent pencil in glass of water","Rainbow","appearing of raised coin in a trough filled with water"],"a":0,"x":"Moonlight is sunlight reflected off the Moon, so it is reflection, not refraction. A bent pencil in water, a rainbow and a coin appearing raised are all refraction.","e":"A rainbow uses refraction, dispersion and internal reflection.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q0493","q":"Which among the following defects is also known as far-sightedness?","o":["Myopia","Cataract","Hypermetropia","Presbyopia"],"a":2,"x":"Hypermetropia (far-sightedness): far objects are clear but near ones blur. It is corrected with a convex lens.","e":"Myopia (near-sightedness) uses a concave lens; presbyopia is age-related loss of near focus.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0614","q":"Which among the following defects is also known as near-sightedness?","o":["Myopia","Cataract","Hypermetropia","Presbyopia"],"a":0,"x":"Myopia (near-sightedness): near objects are clear, distant ones blur because the image forms before the retina. A concave lens corrects it.","e":"Hypermetropia (far-sightedness) is corrected by a convex lens.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q1833","q":"Which of the following is correct pair of position of the object – position of the image – size of image in a concave mirror? I. At infinity – at focus – highly diminished II. At C – At C – enlarged III. At focus – At infinity – highly enlarged","o":["I and II","II and III","I and III","Only III"],"a":2,"x":"In a concave mirror, an object at infinity forms a highly diminished image at the focus; an object at the focus forms a highly enlarged image at infinity; an object at C forms a same-size image at C (not enlarged). So I and III are right.","e":"At C → same size at C.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1987","q":"Which of the following pair is/are correct? I. Convex mirror – object at infinity – image virtual and erect II. Concave mirror – object at C – same sized image","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"A convex mirror always forms a virtual, erect, smaller image, including for an object at infinity; a concave mirror forms a same-size image at C when the object is at C. Both pairs are correct.","e":"Convex mirrors are used as rear-view mirrors.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2029","q":"Which of the following is used by dentist?","o":["Convex mirror","Concave mirror","Convex lens","Concave lens"],"a":1,"x":"Dentists use a concave mirror: held close to a tooth, it gives an enlarged, erect image.","e":"Concave: dentists, shaving mirrors, torches; convex: rear-view mirrors.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2032","q":"Which of the following pair is/are correct? I. Myopia – corrected by concave lens II. Hypermetropia – corrected by convex lens","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Myopia (short sight) is corrected with a concave lens, and hypermetropia (long sight) with a convex lens.","e":"Myopia → concave; hypermetropia → convex.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2110","q":"Which of the following pair of phenomenon – effect is correct? I. Atmospheric refraction – Twinkling of stars II. Atmospheric refraction – Tyndall effect III. Scattering of light – Colour of clear sky being blue IV. Scattering of light – Advance sunrise and delay sunset","o":["I and IV","II and III","I and III","III तथा IV"],"a":2,"x":"Atmospheric refraction makes stars twinkle and causes early sunrise and delayed sunset; scattering makes the sky blue and causes the Tyndall effect. So I and III are correct.","e":"Twinkling = refraction; blue sky = scattering.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q6107","q":"Which of the following pair of mirror–use is correct? I. Convex – Dentist II. Concave – Headlights III. Convex – Side view mirror","o":["Only III","II and III","Only I","Only II"],"a":1,"x":"Concave mirrors are used in headlights (and by dentists); convex mirrors are used as side-view mirrors.","e":"","src":["Junior Clerk 9 Nov 2021 S1"]},{"id":"q4969","q":"Which of the following mirrors are most commonly used by dentists to see an enlarged image of the teeth?","o":["Concave mirrors","Convex mirrors","Bifocal mirrors","Plain mirrors"],"a":0,"x":"Dentists use concave mirrors, which give an enlarged image of the teeth when held close.","e":"","src":["Personal Assistant 26 Nov 2021 S3"]},{"id":"q5183","q":"Which of the following combination is NOT correct with respect to the technology and its corresponding principle?","o":["Sonar - Reflection of ultrasonic waves","Lasers - Controlled nuclear fission","Steam engine - Laws of thermodynamics","Optical fibres - total internal reflection of light"],"a":1,"x":"Lasers work by stimulated emission of radiation, not nuclear fission; the other pairs are correct.","e":"","src":["Personal Assistant 27 Nov 2021 S1"]},{"id":"q5184","q":"The power of a lens of focal length ______ is one dioptre.","o":["1 centimetre","1 millimetre","1 metre","1 nanometre"],"a":2,"x":"A lens of focal length 1 metre has a power of one dioptre (P = 1/f in metres).","e":"","src":["Personal Assistant 27 Nov 2021 S1"]},{"id":"q5375","q":"Which of the following is having lowest frequency?","o":["X Rays","Ultraviolet Rays","Infrared Rays","Gamma Rays"],"a":2,"x":"Of these, infrared rays have the lowest frequency; gamma rays have the highest.","e":"","src":["Personal Assistant 29 Nov 2021 S1"]},{"id":"q3461","q":"Which of the following is not correct about image formation by a concave mirror? I. Object at C, image at C, same sized image II. Object at F, image at F, highly enlarged image III. Object at infinity, image at F, same sized image","o":["I and II","II and III","I and III","I, II and III"],"a":1,"x":"For a concave mirror an object at C gives a same-size image at C (correct). An object at F gives an image at infinity (not at F), and an object at infinity gives a highly diminished image at F (not same size). So II and III are wrong.","e":"","src":["Store Keeper 19 Apr 2021 S3"]},{"id":"q4017","q":"Who designed and built the telescope with increasingly higher magnifying power, in 1608-09?","o":["Alexander Graham Bell","Thomas Edison","Galileo Galilei","Benjamin Franklin"],"a":2,"x":"Galileo Galilei built telescopes of increasing magnifying power in 1609 and used them to study the sky.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S3"]},{"id":"q4336","q":"The phenomenon which causes a rainbow like pattern on the surface of a CD when light falls on it is called:","o":["Dispersion of light","Refraction of light","Reflection of light","Diffraction of Light"],"a":3,"x":"The rainbow colours on a CD come from diffraction of light by its closely spaced tracks.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S3"]},{"id":"q1163","q":"What is the SI unit for measuring luminous intensity in a given direction?","o":["Candela","Roentgen","Curie","Weber"],"a":0,"x":"The candela is the SI unit of luminous intensity; it is one of the seven SI base units.","e":"Lumen = luminous flux; lux = illuminance.","src":["PRT 26 Mar 2026 S3"]},{"id":"q1275","q":"Unlike sound waves, electromagnetic waves can travel through ____________.","o":["Water only","Air only","Solids only","Vacuum"],"a":3,"x":"Electromagnetic waves (light, radio, X-rays) need no medium and travel through a vacuum at 3 × 10⁸ m/s; sound needs a medium.","e":"That is why we see the Sun but cannot hear it.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1365","q":"Malus' Law is related to which of the following subjects?","o":["Inertia","Surface tension","Gravitation","Light"],"a":3,"x":"Malus' law is about polarised light: the intensity passing through an analyser is I = I₀ cos²θ, where θ is the angle between the polariser and analyser.","e":"Polarised sunglasses cut glare using this principle.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1399","q":"How many internal reflections do light rays undergo, inside a raindrop, to form a secondary rainbow?","o":["One","Four","Three","Two"],"a":3,"x":"A secondary rainbow forms after two internal reflections inside raindrops (a primary rainbow after one), so its colours are reversed and fainter.","e":"The primary rainbow has red on the outside; the secondary has red on the inside.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1554","q":"Transverse nature of light causes:","o":["convergent nature of light","reflection of light","polarisation of light","divergent nature of light"],"a":2,"x":"Only transverse waves can be polarised, so polarisation proves that light is a transverse wave.","e":"Sound in air is longitudinal and cannot be polarised.","src":["TGT 31 Aug 2025 S1"]},{"id":"q1653","q":"In a convex lens, when the object is at infinity, then the image is formed at ______.","o":["F2","Between F2 and 2F2","Beyond 2F2","At infinity"],"a":0,"x":"For a convex lens, an object at infinity forms a point image at the principal focus F2.","e":"","src":["TGT 10 Oct 2021 S1"]},{"id":"q1731","q":"Which among the following is the unit of Radiant Flux?","o":["Joule","Watt","Ohm","Tesla"],"a":1,"x":"Radiant flux (radiant power) is measured in watts.","e":"","src":["TGT 10 Sep 2021 S3"]},{"id":"q1899","q":"Who discovered the diffraction of electrons?","o":["Eugene Goldstein","Sir George Thomson","Anderson","Avogadro"],"a":1,"x":"George Paget Thomson (with Davisson and Germer) showed the diffraction of electrons.","e":"","src":["TGT 11 Sep 2021 S3"]},{"id":"q2292","q":"Who has discovered X-Rays?","o":["Roentgen","Anderson","Becquerel","Chadwick"],"a":0,"x":"Wilhelm Roentgen discovered X-rays in 1895.","e":"","src":["TGT 13 Sep 2021 S2"]},{"id":"q2303","q":"The refractive index of water is ______.","o":["1.33","1.9","2.1","2.42"],"a":0,"x":"The refractive index of water is about 1.33.","e":"Diamond: 2.42.","src":["TGT 13 Sep 2021 S3"]},{"id":"q3521","q":"Which of the following statement is correct? I. Myopia can be corrected by using a convex lens of suitable power. II. Hypermetropia can be corrected by using a concave lens of suitable power.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":3,"x":"Both are wrong: myopia is corrected with a concave lens and hypermetropia with a convex lens.","e":"","src":["TGT 1 Oct 2021 S1"]},{"id":"q5703","q":"In the question given below, there are two statements marked as Assertion (A) and Reason (R). Mark your answer as per the codes in options. Assertion (A): When lightning strikes, the flash is seen a little after the sound is heard. Reason (R): Velocity of light is more than the velocity of sound.","o":["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"a":3,"x":"The assertion is false: in lightning the flash is seen before the thunder is heard, because light travels much faster than sound.","e":"","src":["TGT 4 Sep 2021 S2"]},{"id":"q5752","q":"Which of the following is NOT an example of scattering of light?","o":["Reddening of the sun at sunrise & sunset","The color of the sky looks blue","Tyndall effect","Formation of Rainbow"],"a":3,"x":"A rainbow forms by refraction, dispersion and internal reflection, not scattering; red sunsets, the blue sky and the Tyndall effect are due to scattering.","e":"","src":["TGT 5 Sep 2021 S1"]},{"id":"q5845","q":"Which of the following scientists collaborated with Einstein on formulating a theory related to the gas like qualities of electromagnetic radiation?","o":["Subrahmanyam Chandrashekhar","Meghnad Saha","Satyendranath Bose","C.V. Raman"],"a":2,"x":"Satyendra Nath Bose worked with Einstein on the statistics of light quanta (Bose–Einstein statistics).","e":"","src":["TGT 5 Sep 2021 S3"]},{"id":"q5900","q":"The image formed by a concave lens is always ______ and ______.","o":["Real, Inverted","Real, erect","Virtual, inverted","Virtual, erect"],"a":3,"x":"A concave lens always forms a virtual, erect and diminished image.","e":"","src":["TGT 6 Sep 2021 S3"]},{"id":"q7487","q":"Which of the following happens due to atmospheric refraction? I. Twinkling of stars II. Advanced sunrise and delayed sunset","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Atmospheric refraction causes the twinkling of stars and makes sunrise earlier and sunset later.","e":"","src":["TGT 1 Aug 2021"]},{"id":"q7510","q":"In a concave mirror, when object is at inflinity then image is ______.","o":["at C","at F","beyond C","at infinity"],"a":1,"x":"For a concave mirror, an object at infinity forms a point image at the focus F.","e":"","src":["TGT 1 Aug 2021"]},{"id":"q7554","q":"In a concave mirror, when object is at C then size of image is ______.","o":["of same size","highly diminished","enlarged","highly enlarged"],"a":0,"x":"For a concave mirror, an object at C forms a real, inverted image of the same size at C.","e":"","src":["TGT 7 Aug 2021"]},{"id":"q6567","q":"Which among the following is an example of electromagnetic waves?","o":["Cathode Rays","Canal Rays","X-Rays","Ultrasonic Rays"],"a":2,"x":"X-rays are electromagnetic waves; cathode rays and canal rays are particle streams and ultrasonic waves are sound.","e":"","src":["PGT 3 Jul 2021 S1"]},{"id":"q7160","q":"According to _________ law, when an unpolarized light of known wavelength is incident on a transparent substance's surface, it experiences maximum plane polarization at the angle of incidence whose tangent is the refractive index of the substance for the wavelength.","o":["Lenz's","Joule's","Murphy's","Brewster’s"],"a":3,"x":"Brewster's law: reflected light is fully polarised when the tangent of the angle of incidence equals the refractive index.","e":"","src":["PGT 31 Jul 2021 S1"]},{"id":"q7189","q":"Which among the following statements is incorrect?","o":["The point at which the incident ray falls on the mirror surface is called point of incidence.","The angle made by the incident ray with the normal is called angle of incidence.","A line perpendicular or at the right angle to the mirror surface at the point of incidence is called the normal.","According to the first law of reflection, the angle of reflection is always equal to the angle of incidence."],"a":3,"x":"Angle of reflection = angle of incidence is the second law of reflection; the first law says the incident ray, normal and reflected ray lie in one plane.","e":"","src":["PGT 16 Jul 2021 S2"]},{"id":"q7754","q":"Where is the reflecting surface of a Concave Mirror curved?","o":["Outwards","Upwards","Downwards","Inwards"],"a":3,"x":"A concave mirror's reflecting surface curves inwards.","e":"","src":["PGT 22 Jul 2021"]},{"id":"q8557","q":"Which of the following technologies is INCORRECTLY matched with the scientific principle?","o":["Steam Engine – Law of Thermodynamics","Nuclear Reactors – Photoelectric effect","Computers – Digital Logic","Rocket Propulsion – Newton’s laws of motion"],"a":1,"x":"Nuclear reactors work on nuclear fission, not the photoelectric effect.","e":"","src":["PGT 3 Nov 2022"]},{"id":"q9541","q":"Which among the following is not a property of electromagnetic waves?","o":["They are positively charged.","They contain energy and momentum.","They propagate as transverse waves.","They propagate with the velocity of light."],"a":0,"x":"Electromagnetic waves carry no charge; they are transverse, carry energy and momentum, and travel at the speed of light.","e":"","src":["PGT 30 Jun 2021 S1"]},{"id":"q9850","q":"Identify whether the following statements are true or false with respect to reflection of light from a plane mirror. A. Angle of incidence and angle of reflection for a ray of light might differ for few cases. B. The ray of incidence, ray of reflection and the normal always lie on the same plane. C. The phenomenon of lateral inversion is an intrinsic property of light.","o":["A-True ; B-False ; C-True","A-True ; B-False ; C-False","A-True ; B-True ; C-False","A-False ; B-True ; C-False"],"a":3,"x":"The angles of incidence and reflection are always equal, and the incident ray, reflected ray and normal lie in one plane.","e":"","src":["PGT 16 Jul 2025"]},{"id":"q1633","q":"Which of the following pair of position of Object – Position of image is CORRECT regarding concave mirror? I. At infinity – At F II. At F – At C","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"In a concave mirror, an object at infinity forms an image at F; an object at F forms an image at infinity, not at C.","e":"","src":["Senior Scientific Assistant (Lie-Detection) 10 Oct 2021 S1"]},{"id":"q3967","q":"Who was the founder of the 'Wave Theory of Light' from following?","o":["Hugo Grotius","Christiaan Huygens","Baruch Spinoza","William B Drees"],"a":1,"x":"Christiaan Huygens proposed the wave theory of light.","e":"","src":["Trained Graduate Teacher (Deaf & Dumb) Tier-I 22 Nov 2021 S2"]},{"id":"q4252","q":"In which year was the X-radiation discovered by W Roentgen?","o":["1865","1895","1885","1875"],"a":1,"x":"Wilhelm Röntgen discovered X-rays in 1895.","e":"","src":["Workshop Instructor 24 Nov 2021 S1"]},{"id":"q4766","q":"The ability of a medium to refract light is expressed in terms of which of the following?","o":["Refractive Index","Optical Density","Mass Density","Speed of Light in the medium"],"a":1,"x":"The ability of a medium to refract light is expressed as its optical density (NCERT).","e":"","src":["Scientific Assistant (Documents) 25 Sep 2021 S2"]},{"id":"q5100","q":"When an object is placed very close to a concave mirror, what is the nature of the image formed?","o":["Virtual, erect and magnified","Real, erect and smaller in size","Virtual, Inverted and smaller in size","Virtual, erect and diminished in size"],"a":0,"x":"An object very close to a concave mirror (within F) gives a virtual, erect, magnified image.","e":"","src":["Laboratory Assistant (Photo) 26 Sep 2021 S2"]},{"id":"q5227","q":"Refractive index of Ice is _________.","o":["1.85","1.31","1.50","1.77"],"a":1,"x":"The refractive index of ice is about 1.31.","e":"","src":["Senior Scientific Assistant (Chemistry) 27 Sep 2021 S2"]}]},{"id":"electricity","n":"Electricity and Magnetism","qs":[{"id":"q0224","q":"When the discharge takes place between opposite charges accumulated in different clouds, the type of lightning produced is:","o":["cloud to air lightning","cloud to ground lightning","cloud to cloud lightning","intra cloud lightning"],"a":2,"x":"When charges jump between oppositely charged regions of two different clouds, the result is cloud-to-cloud (inter-cloud) lightning.","e":"Inside a single cloud it is intra-cloud lightning; the most dangerous kind is cloud-to-ground.","src":["ASO 20 Aug 2025 S1"]},{"id":"q1605","q":"Which of the following is NOT a basic feature of magnets?","o":["Directive property","Magnet exists as a monopole","Attractive property","Like poles repel and unlike poles attract"],"a":1,"x":"A magnet always has two poles (north and south); a magnetic monopole has never been found. Cut a magnet in half and each piece has both poles.","e":"Magnets attract iron, point north–south when free, and like poles repel.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q0533","q":"Which among the following laws states that the current passing through a conductor between two points is directly proportional to the potential difference across the two points provided the physical state and temperature etc. of the conductor does not change?","o":["Ohm's Law","Avogadro's Law","Coulomb’s Law","Pascal’s Law"],"a":0,"x":"Ohm's law: at constant temperature, the current through a conductor is directly proportional to the potential difference across it (V = IR).","e":"A 12 V battery across a 4 Ω resistor drives 3 A.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0574","q":"Which among the following laws states that induced electromotive force with different polarities induces a current whose magnetic field opposes the change in magnetic flux through the loop in order to ensure that original flux is maintained through the loop when current flows in it?","o":["Lenz's Law","Ohm's Law","Snell's Law","Boyle's Law"],"a":0,"x":"Lenz's law: the induced current flows in a direction whose magnetic field opposes the change in flux that produced it. This follows from conservation of energy.","e":"It explains the minus sign in Faraday's law.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0651","q":"An electric generator is a device that converts _______________ energy into electrical energy.","o":["sound","chemical","nuclear","mechanical"],"a":3,"x":"An electric generator (dynamo) converts mechanical energy into electrical energy through electromagnetic induction.","e":"An electric motor does the reverse.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q1914","q":"Which of the following is not a unit of Electric Power?","o":["Watts","Joule per second","Volt per metre","Calorie per second"],"a":2,"x":"Power is energy per time: watt, joule per second and calorie per second are all power units. Volt per metre is the unit of electric field, not power.","e":"1 W = 1 J/s; 1 calorie ≈ 4.186 J.","src":["Junior Clerk 13 Nov 2021 S3","Scientific Assistant (Ballistics) 11 Sep 2021 S3"]},{"id":"q3865","q":"In Microphone, sound energy is converted to ___________ energy.","o":["electrical","chemical","mechanical","wind"],"a":0,"x":"A microphone converts sound energy into electrical energy; a loudspeaker does the reverse.","e":"","src":["Store Keeper 22 Apr 2021 S3"]},{"id":"q2756","q":"The SI unit of Resistance is ________.","o":["Watt","Ohm","Joule","Pascal"],"a":1,"x":"The SI unit of resistance is the ohm (Ω).","e":"V = IR.","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q2827","q":"According to which of the following laws, the direction of induced electromotive force or induced current is always in such a way that it opposes the cause due to which it is produced?","o":["Ohm's Law","Boyle's Law","Lenz's Law","Charles' Law"],"a":2,"x":"Lenz's law: the induced current always flows in a direction that opposes the change that produced it (a result of conservation of energy).","e":"","src":["Ahlmad 16 Oct 2021 S3"]},{"id":"q4335","q":"With regard to electrical properties, Silicon can be classified as a:","o":["Semiconductor","Insulator","Conductor","Absorber"],"a":0,"x":"Silicon is a semiconductor; its conductivity lies between that of conductors and insulators.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S3"]},{"id":"q6352","q":"Who did the alpha particle scattering experiment?","o":["Thomson","Goldstein","Rutherford","Bohr"],"a":2,"x":"Ernest Rutherford did the alpha-particle scattering (gold foil) experiment and discovered the nucleus.","e":"","src":["Care Taker 8 Aug 2021"]},{"id":"q0912","q":"Electric and magnetic fields are regarded as:","o":["Scalar quantities because they have only magnitude","Non-physical entities without measurable effects","Independent phenomena with no relation","Vector quantities because they have both magnitude and direction"],"a":3,"x":"Electric and magnetic fields are vector quantities: they have both magnitude and direction at every point.","e":"Other vectors: force, velocity. Scalars: mass, temperature, energy.","src":["PRT 17 Feb 2026 S3"]},{"id":"q1096","q":"Where is the magnetic field strongest on a magnet?","o":["At the poles","Only at one end","Equally everywhere","At the centre"],"a":0,"x":"A magnet's field is strongest at its poles, where field lines are closest together; that is why iron filings cluster at the ends.","e":"Like poles repel, unlike poles attract.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1122","q":"What is the force between two small charged particles of 4 × 10⁻⁶ C and 6 × 10⁻⁶ C placed 20 cm apart in air?","o":["5.4 × 10⁻² N","5.4 × 10⁻⁴ N","5.4 N","5400 N"],"a":2,"x":"By Coulomb's law F = k·q₁q₂/r² = 9×10⁹ × (4×10⁻⁶ × 6×10⁻⁶) / (0.2)² = 0.216/0.04 = 5.4 N.","e":"Double the distance → force drops to a quarter.","src":["PRT 26 Mar 2026 S1"]},{"id":"q3311","q":"A cathode-ray tube is an integral part of which of these appliances?","o":["Air- conditioner","Microwave","Radio","Television"],"a":3,"x":"A cathode-ray tube was the picture tube of old television sets.","e":"","src":["TGT 18 Sep 2021 S1"]},{"id":"q3356","q":"Radio waves used for signalling and communication can be classified as which of the following?","o":["electromagnetic waves","longitudinal waves","gravitational waves","transverse waves"],"a":0,"x":"Radio waves are electromagnetic waves.","e":"","src":["TGT 18 Sep 2021 S2"]},{"id":"q5039","q":"Electric Motor converts ________.","o":["Electrical energy into mechanical energy","Mechanical energy into Electrical energy","Electrical energy into light energy","light energy into mechanical energy"],"a":0,"x":"An electric motor converts electrical energy into mechanical energy; a generator does the reverse.","e":"","src":["TGT 26 Sep 2021 S1"]},{"id":"q5076","q":"Which of the following is used in the treatment of cancer?","o":["Cobalt-60","Iron-56","Nickel-64","Aluminium-27"],"a":0,"x":"Cobalt-60, a radioactive isotope, is used in cancer radiotherapy.","e":"","src":["TGT 26 Sep 2021 S2"]},{"id":"q5729","q":"The magnetron is an electron tube found in which of these household appliances?","o":["Water purifier","Remote control","Microwave","Refrigerator"],"a":2,"x":"A magnetron produces the microwaves in a microwave oven.","e":"","src":["TGT 4 Sep 2021 S3"]},{"id":"q5880","q":"Which of the following is NOT correct for electric potential difference?","o":["V = (W/Q)","W = V × Q","= (W/V)","V = W × Q"],"a":3,"x":"Potential difference V = W/Q, so W = VQ and Q = W/V; V = W × Q is wrong.","e":"","src":["TGT 6 Sep 2021 S2"]},{"id":"q5951","q":"No force acts on a current carrying conductor when it is placed ______.","o":["far away from the magnetic field","perpendicular to the magnetic field","parallel to the magnetic field","inside a magnetic field"],"a":2,"x":"No force acts on a current-carrying conductor placed parallel to a magnetic field; the force is greatest when it is perpendicular.","e":"","src":["TGT 7 Sep 2021 S2"]},{"id":"q5967","q":"The unit of Electromotive force of a cell is ______.","o":["Joule","Ampere","Dyne","Volt"],"a":3,"x":"The unit of electromotive force is the volt.","e":"","src":["TGT 7 Sep 2021 S3"]},{"id":"q6240","q":"Which of the following statement is correct? I. The magnetic field inside a long straight solenoid carrying current is same at all the points. II. The magnetic field of a solenoid carrying a current is similar to that of bar magnet.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The magnetic field inside a long solenoid is uniform, and its field pattern is like that of a bar magnet.","e":"","src":["TGT 9 Oct 2021 S1"]},{"id":"q8024","q":"Which of the following elements is used in the manufacturing of solar cells?","o":["Carbon","Silicon","Lithium","Nickel"],"a":1,"x":"Solar cells are mainly made of silicon.","e":"","src":["TGT 6 Jul 2023 S2"]},{"id":"q6492","q":"Which among the following statements is incorrect?","o":["Gamma Rays are electromagnetic radiations of low wavelength, high frequency and high energy.","Beta particles are positively charged light particles.","The isotopes which are unstable (due to presence of extra neutrons in their nuclei) and emit various types of radiation are called radioactive Isotopes.","Chain reaction is the phenomenon in which neutrons liberated during a fission process lead to a further fission of atoms, releasing a large amount of energy."],"a":1,"x":"Beta particles are negatively charged electrons, so statement B is wrong.","e":"","src":["PGT 23 Jul 2021 S1"]},{"id":"q6590","q":"The unit of self-inductance is _________.","o":["Henry","Ampere","Candela","Kelvin"],"a":0,"x":"The SI unit of self-inductance is the henry.","e":"","src":["PGT 3 Jul 2021 S2"]},{"id":"q2650","q":"Which of the following electromagnetic waves is used most commonly in point to point communication systems?","o":["X- Rays","Microwaves","Infrared Rays","Gamma Rays"],"a":1,"x":"Microwaves are most used in point-to-point communication links.","e":"","src":["Technical Assistant (Interior Design) 16 Nov 2021 S1"]},{"id":"q4808","q":"A lightning conductor is made of which of the following?","o":["Metal","Non-Metal","Metalloid","Gas"],"a":0,"x":"A lightning conductor is made of metal, usually copper.","e":"","src":["Scientific Assistant (Chemistry) 25 Sep 2021 S3"]}]}]});
